# 1. Sysmon Event ID 1 (process creation): Office applications that started a shell
$sysmon = @{ LogName = 'Microsoft-Windows-Sysmon/Operational'; Id = 1; StartTime = (Get-Date).AddDays(-1) }
Get-WinEvent -FilterHashtable $sysmon | ForEach-Object {
    $d = @{}; ([xml]$_.ToXml()).Event.EventData.Data | ForEach-Object { $d[$_.Name] = $_.'#text' }
    [pscustomobject]@{
        Time        = $_.TimeCreated
        User        = $d.User
        Parent      = Split-Path $d.ParentImage -Leaf
        Image       = Split-Path $d.Image -Leaf
        CommandLine = $d.CommandLine
        ProcessGuid = $d.ProcessGuid
    }
} | Where-Object { $_.Parent -match 'winword|excel|outlook' -and $_.Image -match 'powershell|cmd|wscript|mshta' }

