# 2. Sysmon Event ID 3 (network connection) for that exact process
Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Sysmon/Operational'; Id = 3 } |
    Where-Object { $_.Message -match '5c1f8a2e-4b31-672d-a104-000000000b00' } |
    Select-Object -First 1 -ExpandProperty Message

# DestinationIp: 203.0.113.50   DestinationPort: 443   Initiated: true

# 3. Microsoft Defender: detections (1116), actions (1117), protection disabled (5001), config changed (5007)
Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Windows Defender/Operational'; Id = 1116, 1117, 5001, 5007 } -MaxEvents 5 |
    Select-Object TimeCreated, Id, @{ n = 'Summary'; e = { ($_.Message -split "`n")[0] } }

